// Package rpcdifftest is the service of the differential tests of the net/rpc and net/http
// models (models/net/rpc, models/net/http): run.sh runs the tests (rpc_test.go) twice, against
// Go's real packages and against the models (`go test -overlay`, models/goroot.py, tag
// netmodel), and every test must pass in both. Its codec for the model (codec/) is generated by
// models/net/rpc/rpcgen.py from rpc.toml. (From dsverify-lab's harness/rpcmodel/difftest.)
package rpcdifftest

import (
	"errors"
	"sync"
)

type Args struct {
	A uint64
	B uint64
}

type Reply struct {
	C uint64
}

type Tags map[string]uint64

// Arith is the test service.
type Arith struct {
	mu    sync.Mutex
	runs  map[uint64]uint64 // Count: runs per call id
	gates map[uint64]chan bool
}

func NewArith() *Arith {
	return &Arith{runs: make(map[uint64]uint64), gates: make(map[uint64]chan bool)}
}

func (t *Arith) gate(id uint64) chan bool {
	t.mu.Lock()
	defer t.mu.Unlock()
	ch, ok := t.gates[id]
	if !ok {
		ch = make(chan bool)
		t.gates[id] = ch
	}
	return ch
}

func (t *Arith) Add(a *Args, r *Reply) error {
	r.C = a.A + a.B
	return nil
}

func (t *Arith) Fail(a *Args, r *Reply) error {
	r.C = 7
	return errors.New("arith: fail")
}

func (t *Arith) Echo(s string, r *string) error {
	*r = s
	return nil
}

func (t *Arith) Keys(m *Tags, r *Tags) error {
	*r = Tags{}
	for k, v := range *m {
		(*r)[k+"!"] = v + 1
	}
	return nil
}

// Wait blocks until Signal(a.A) runs.
func (t *Arith) Wait(a *Args, r *Reply) error {
	<-t.gate(a.A)
	r.C = a.A
	return nil
}

// Signal releases Wait(a.A).
func (t *Arith) Signal(a *Args, r *Reply) error {
	close(t.gate(a.A))
	return nil
}

// Count records a run of call a.A.
func (t *Arith) Count(a *Args, r *Reply) error {
	t.mu.Lock()
	t.runs[a.A]++
	t.mu.Unlock()
	r.C = a.A
	return nil
}

func (t *Arith) Runs(id uint64) uint64 {
	t.mu.Lock()
	defer t.mu.Unlock()
	return t.runs[id]
}

// Nums carries the integer types other than uint64.
type Nums struct {
	I int
	J int32
	K uint8
}

// Neg negates I and J and complements K.
func (t *Arith) Neg(a *Nums, r *Nums) error {
	r.I, r.J, r.K = -a.I, -a.J, ^a.K
	return nil
}

// Greeter is registered by rpc.Register, under its type's name.
type Greeter struct{}

func (g *Greeter) Hello(s string, r *string) error {
	*r = "hello " + s
	return nil
}

// NoMethods has no method net/rpc registers (Get's signature is not func(T1, *T2) error):
// registering it is an error.
type NoMethods struct{ n uint64 }

func (t *NoMethods) Get() uint64 { return t.n }
